function findLooseRanges(node, depth = 0, results = []) {
  if (node.range !== null && isLooseRange(node.range)) {
    results.push({ name: node.name, range: node.range, resolved: node.resolved, depth });
  }
  for (const child of node.dependencies) {
    findLooseRanges(child, depth + 1, results);
  }
  return results;
}

