function countPinnedVsLoose(node) {
  let pinned = 0;
  let loose = 0;
  function walk(n) {
    if (n.range !== null) {
      if (isLooseRange(n.range)) loose++;
      else pinned++;
    }
    for (const child of n.dependencies) walk(child);
  }
  walk(node);
  return { pinned, loose };
}

