  // TODO: return { name, distance } for every popular package within maxDistance
  // of candidateName (excluding an exact match), sorted by ascending distance
}

items.solution:
function findTyposquatCandidates(candidateName, popularPackages, maxDistance) {
  return popularPackages
    .filter((name) => name !== candidateName)
    .map((name) => ({ name, distance: levenshtein(candidateName, name) }))
    .filter((entry) => entry.distance > 0 && entry.distance <= maxDistance)
    .sort((a, b) => a.distance - b.distance);
}

